def transform(grid):
    # Identify Background (dominant value)
    bg = 9
    # Identify Signal (scattered value to be overwritten)
    signal = 8

    # Extract Pattern (all non-BG, non-Signal pixels)
    pattern = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            if val != bg and val != signal:
                pattern.append((r, c, val))

    # If no pattern, return original grid
    if not pattern:
        return grid

    # Calculate geometric center of the pattern
    rows = [p[0] for p in pattern]
    cols = [p[1] for p in pattern]
    center_r = sum(rows) // len(pattern)
    center_c = sum(cols) // len(pattern)

    # Create output grid initialized as a copy of input
    output = [row[:] for row in grid]

    # Create a map of relative offsets to values for the pattern
    p_map = {}
    for r, c, val in pattern:
        dr = r - center_r
        dc = c - center_c
        p_map[(dr, dc)] = val

    # Find all Signal pixels
    signals = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == signal:
                signals.append((r, c))

    # Copy the Pattern to each Signal pixel location
    for sr, sc in signals:
        for (dr, dc), val in p_map.items():
            nr = sr + dr
            nc = sc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                output[nr][nc] = val

    return output
