def transform(grid):
    # 1. Identify Background (Most frequent value)
    counts = {}
    for row in grid:
        for val in row:
            counts[val] = counts.get(val, 0) + 1
    bg_val = max(counts, key=counts.get)

    # 2. Identify Connected Components of non-BG pixels
    visited = [[False] * len(grid[0]) for _ in range(len(grid))]
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg_val and not visited[r][c]:
                comp = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc, grid[cr][cc]))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] != bg_val and not visited[nr][nc]:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                if comp:
                    components.append(comp)

    # 3. Identify Pattern Component (Largest)
    # In all demos, the Pattern is the largest connected cluster of non-background pixels.
    # Signal pixels are scattered/isolated (size 1) and non-connected.
    pattern_comp = max(components, key=len) if components else []

    # 4. Extract Pattern Source Info
    if not pattern_comp:
        return grid

    rows = [p[0] for p in pattern_comp]
    cols = [p[1] for p in pattern_comp]
    center_r = sum(rows) // len(pattern_comp)
    center_c = sum(cols) // len(pattern_comp)

    # Prepare Value Map for Pattern
    p_map = {}
    for r, c, val in pattern_comp:
        p_map[(r - center_r, c - center_c)] = val

    # 5. Identify Signal Targets
    # Signal Targets are all non-BG pixels NOT in Pattern Component
    pattern_coords = set((r, c) for r, c, val in pattern_comp)
    signal_locs = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != bg_val and (r, c) not in pattern_coords:
                signal_locs.append((r, c))

    # 6. Copy Pattern to Signal Targets
    output = [row[:] for row in grid]
    for sr, sc in signal_locs:
        for (dr, dc), val in p_map.items():
            nr = sr + dr
            nc = sc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                output[nr][nc] = val

    return output
